package com.oms.order.service;
import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static org.junit.jupiter.api.Assertions.*;
class OrderBundleTest {
 OrderRepositoryTest f;
 @BeforeAll static void start(){OrderRepositoryTest.start();}
 @AfterAll static void stop(){OrderRepositoryTest.stop();}
 @BeforeEach void setup(){f=new OrderRepositoryTest();f.clear();f.db.update("DELETE FROM oms_order_bundle");}
 Map<String,Object> m(Object...v){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)r.put(v[i].toString(),v[i+1]);return r;}
 Map<String,Object> kit(){return m("enabled",1,"revision",3,"sku_sn","S","goods_name","Kit S","components",Arrays.asList(m("sku_sn","A","goods_name","Part A","quantity",2),m("sku_sn","B","goods_name","Part B","quantity",1)));}
 @Test void conversionKeepsOneSalesParentAndTwoDistinctStockLinesWithRealOid(){String payload=TmallOrderParserTest.payload("25");f.repository.page("VERIFY",1,f.LEASE,f.task("MANUAL"),Collections.singletonList(f.row("2026-10-01 01:00:00",payload)),50);long platform=f.n("SELECT id FROM oms_platform_order");f.repository.snapshot("VERIFY",platform,f.LEASE);TmallOrderParser.Trade t=new TmallOrderParser().parse(payload);String oid=t.lines.get(0).oid;f.repository.parsed("VERIFY",platform,f.LEASE,t,Collections.singletonMap(oid,"S"),Collections.emptyMap());f.repository.bundleSnapshots("VERIFY",platform,f.LEASE,Collections.singletonMap(oid,kit()));f.repository.complete("VERIFY",platform,f.LEASE,f.repository.config("VERIFY",1),Arrays.asList(m("platform_oid",oid,"sku_sn","A","reserved_quantity",10,"reason",""),m("platform_oid",oid,"sku_sn","B","reserved_quantity",5,"reason","")));assertEquals(1,f.n("SELECT COUNT(*) FROM oms_order_bundle"));assertEquals(2,f.n("SELECT COUNT(*) FROM oms_order_line"));assertEquals(1,f.n("SELECT COUNT(DISTINCT platform_oid) FROM oms_order_line"));assertEquals(0,f.n("SELECT SUM(payment) FROM oms_order_line"));assertEquals(5,f.n("SELECT quantity FROM oms_order_bundle"));assertEquals(3,f.n("SELECT revision FROM oms_order_bundle"));assertEquals("Part A",f.db.queryForObject("SELECT goods_name FROM oms_order_line WHERE sku_sn='A'",String.class));List<Map<String,Object>> report=OrderBundles.report(f.repository,"VERIFY",f.n("SELECT id FROM oms_order"));assertEquals(1,report.size());assertEquals(2,((List<?>)report.get(0).get("components")).size());assertFalse(report.get(0).containsKey("units"));}
 @Test void giftParentsWithSharedComponentsPersistWithoutFakePlatformOids(){String payload=TmallOrderParserTest.payload("25");f.repository.page("VERIFY",1,f.LEASE,f.task("MANUAL"),Collections.singletonList(f.row("2026-10-01 01:00:00",payload)),50);long platform=f.n("SELECT id FROM oms_platform_order");f.repository.snapshot("VERIFY",platform,f.LEASE);TmallOrderParser.Trade trade=new TmallOrderParser().parse(payload);String oid=trade.lines.get(0).oid;f.repository.parsed("VERIFY",platform,f.LEASE,trade,Collections.singletonMap(oid,"A"),Collections.emptyMap());Map<String,Map<String,Object>> products=new HashMap<>();for(String sku:Arrays.asList("X","Y"))products.put(sku,m("goods_name",sku,"is_gift",1,"is_package",1,"bundle",kit()));List<Map<String,Object>> parents=GiftProducts.freeze(Arrays.asList(m("sku_sn","X","quantity",1,"payment",java.math.BigDecimal.ZERO,"platform_oid",""),m("sku_sn","Y","quantity",1,"payment",java.math.BigDecimal.ZERO,"platform_oid","")),products,42),gifts=GiftProducts.expand(parents);for(Map<String,Object> gift:gifts)gift.put("gift_plan_id",42L);GiftService service=org.mockito.Mockito.mock(GiftService.class);org.springframework.beans.factory.ObjectProvider<GiftService> provider=org.mockito.Mockito.mock(org.springframework.beans.factory.ObjectProvider.class);org.mockito.Mockito.when(provider.getIfAvailable()).thenReturn(service);org.mockito.Mockito.when(service.prepared("VERIFY",platform)).thenReturn(gifts);org.springframework.test.util.ReflectionTestUtils.setField(f.repository,"giftProvider",provider);try{List<Map<String,Object>> receipts=new ArrayList<>();receipts.add(m("platform_oid",oid,"sku_sn","A","reserved_quantity",5,"reason",""));for(Map<String,Object> gift:gifts)receipts.add(m("platform_oid","","stock_reference",gift.get("stock_reference"),"sku_sn",gift.get("sku_sn"),"reserved_quantity",gift.get("quantity"),"reason",""));f.repository.complete("VERIFY",platform,f.LEASE,f.repository.config("VERIFY",1),receipts);assertEquals(5,f.n("SELECT COUNT(*) FROM oms_order_line"));assertEquals(2,f.n("SELECT COUNT(*) FROM oms_order_bundle WHERE gift_plan_id=42 AND platform_oid=''"));assertEquals(2,f.n("SELECT COUNT(DISTINCT bundle_id) FROM oms_order_line WHERE gift_plan_id=42"));assertEquals(4,f.n("SELECT COUNT(*) FROM oms_order_line WHERE gift_plan_id=42 AND platform_oid='' AND stock_reference LIKE 'GIFT:%'"));assertEquals(5,f.n("SELECT quantity FROM oms_order_line WHERE gift_plan_id IS NULL"));assertEquals(0,f.n("SELECT SUM(payment) FROM oms_order_line WHERE gift_plan_id=42"));}finally{org.springframework.test.util.ReflectionTestUtils.setField(f.repository,"giftProvider",null);}}
 @Test void changingDefinitionCannotRewriteFrozenDemandSnapshot(){String payload=TmallOrderParserTest.payload("25");f.repository.page("VERIFY",1,f.LEASE,f.task("MANUAL"),Collections.singletonList(f.row("2026-10-01 01:00:00",payload)),50);long p=f.n("SELECT id FROM oms_platform_order");f.repository.snapshot("VERIFY",p,f.LEASE);TmallOrderParser.Trade t=new TmallOrderParser().parse(payload);String oid=t.lines.get(0).oid;f.repository.parsed("VERIFY",p,f.LEASE,t,Collections.singletonMap(oid,"S"),Collections.emptyMap());f.repository.bundleSnapshots("VERIFY",p,f.LEASE,Collections.singletonMap(oid,kit()));Map<String,Object> newer=kit();newer.put("revision",4);f.repository.bundleSnapshots("VERIFY",p,f.LEASE,Collections.singletonMap(oid,newer));assertEquals(3,number(f.repository.bundleSnapshots("VERIFY",p).get(oid),"revision"));}
 @Test void unpublishedOrInvalidCompositionCannotEnterDemand(){assertThrows(IllegalArgumentException.class,()->OrderBundles.snapshot("S","Kit",m("bundle",m("enabled",0,"revision",1,"components",Collections.emptyList()))));Map<String,Object> invalid=kit();invalid.put("components",Arrays.asList(m("sku_sn","S","quantity",1)));assertThrows(IllegalArgumentException.class,()->OrderBundles.snapshot("S","Kit",m("bundle",invalid)));}
 @Test void stockedKitKeepsParentDemandAndPaymentInsteadOfExpandingComponents(){Map<String,Object> k=kit();k.put("inventory_mode","STOCKED");Map<String,Object> line=m("platform_oid","123","quantity",2,"payment",new java.math.BigDecimal("20"),"bundle_snapshot",k);List<Map<String,Object>> result=OrderBundles.expand(Arrays.asList(line));assertEquals(1,result.size());assertEquals("S",result.get(0).get("sku_sn"));assertEquals(2,result.get(0).get("quantity"));assertEquals(new java.math.BigDecimal("20"),result.get(0).get("payment"));assertNotNull(result.get(0).get("stocked_bundle_snapshot"));assertNull(result.get(0).get("bundle_snapshot"));}
 @Test void missingCoefficientNeverDefaultsToOne(){assertThrows(IllegalArgumentException.class,()->OrderBundles.coefficient(m("component_quantity",0)));}
}
